def u(x, unit):
    if '^' in unit:
        base, ex = unit.split('^')
        return M(f'{x}\\ \\text{{{base}}}^{{{ex}}}')
    return M(f'{x}\\ \\text{{{unit}}}')
def fm(x):
    s = format(Dc(str(x)).normalize(), 'f'); return s
def Wv(ans, cand, unit, k=3):
    out = []
    for c in cand:
        c = Dc(str(c))
        if c != Dc(str(ans)) and c > 0 and c not in out: out.append(c)
    t = 1
    while len(out) < k:
        c = Dc(str(ans)) + t * (1 if t % 2 else -1) * max(Dc(1), Dc(str(ans)) / 10); t += 1
        if c > 0 and c != Dc(str(ans)) and c not in out: out.append(c)
    return [u(fm(c), unit) for c in out[:k]]
